def test_relay_cell_is_the_back_half_centroid_north_of_the_hub():
    gate = chart.gateway(11)
    pts = [chart.castles(11)[c] for c in gate['back']]
    centroid = [round(sum(p[0] for p in pts) / len(pts)),
                round(sum(p[1] for p in pts) / len(pts))]
    assert centroid == [508, 264]
    hub = chart.castles(11)[gate['hub']]
    assert hub == (504, 480) and hub[1] - centroid[1] == 216


